import numpy as np
L=open('answer.xyz').read().split('\n')
n=int(L[0])
sym=[l.split()[0] for l in L[2:2+n]]
xyz=np.array([[float(x) for x in l.split()[1:4]] for l in L[2:2+n]])
rad={'H':0.35,'C':0.77,'N':0.72,'Ir':1.40,'Cd':1.45}
bonds={i:[] for i in range(n)}
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(xyz[i]-xyz[j])
        if d < (rad[sym[i]]+rad[sym[j]])*1.25:
            bonds[i].append(j); bonds[j].append(i)
from collections import Counter
print('formula',Counter(sym))
# degrees check
for i in range(n):
    deg=len(bonds[i])
    if sym[i]=='H' and deg!=1: print('H odd',i,deg,[sym[j] for j in bonds[i]])
    if sym[i]=='C' and deg!=4 and i not in (0,): print('C',i,deg,[(j,sym[j]) for j in bonds[i]])
    if sym[i]=='N' and deg!=3: print('N',i,deg)
print('Ir',bonds[0],[sym[j] for j in bonds[0]])
print('Cd',bonds[1],[sym[j] for j in bonds[1]])
# min nonbonded distance
dm=np.linalg.norm(xyz[:,None]-xyz[None],axis=-1)+np.eye(n)*99
print('min dist',dm.min())
bad=[(i,j) for i in range(n) for j in range(i+1,n) if dm[i,j]<1.6 and j not in bonds[i]]
print('clashes',bad[:10])
